  1	import { useEffect, useRef, useState } from 'react';
  2	import type { CSSProperties } from 'react';
  3	import { Citation, QAHistory } from '../../shared/types';
  4	import { describeConfidence, formatTimestamp } from './conversation-format';
  5	
  6	export type HistoryLoadState = 'loading' | 'loaded' | 'error';
  7	
  8	export interface AskError {
  9	  question: string;
 10	  message: string;
 11	}
 12	
 13	interface Props {
 14	  history: QAHistory[];
 15	  loadState: HistoryLoadState;
 16	  pendingQuestion: string | null;
 17	  askError: AskError | null;
 18	  documentCount: number;
 19	  selectedDocId: string | null;
 20	  /** Resolves to false when the cited document no longer exists. */
 21	  onOpenCitation: (citation: Citation) => Promise<boolean>;
 22	  onRetry: (question: string) => void;
 23	  onDismissError: () => void;
 24	  onReloadHistory: () => void;
 25	  /** Resolves to false when clearing failed. */
 26	  onClear: () => Promise<boolean>;
 27	}
 28	
 29	const palette = {
 30	  panel: '#16213e',
 31	  card: '#1a1a3e',
 32	  border: '#0f3460',
 33	  accent: '#533483',
 34	  text: '#e0e0e0',
 35	  muted: '#8888bb',
 36	  error: '#d9534f',
 37	};
 38	
 39	const smallButton: CSSProperties = {
 40	  padding: '4px 10px',
 41	  background: palette.border,
 42	  color: palette.text,
 43	  border: '1px solid #1a1a4e',
 44	  borderRadius: '4px',
 45	  cursor: 'pointer',
 46	  fontSize: '12px',
 47	};
 48	
 49	const turnLabel: CSSProperties = {
 50	  fontSize: '11px',
 51	  fontWeight: 600,
 52	  textTransform: 'uppercase',
 53	  letterSpacing: '0.05em',
 54	  color: palette.muted,
 55	  marginBottom: '4px',
 56	};
 57	
 58	const textBlock: CSSProperties = {
 59	  fontSize: '14px',
 60	  lineHeight: 1.6,
 61	  whiteSpace: 'pre-wrap',
 62	  overflowWrap: 'anywhere',
 63	};
 64	
 65	function citationKey(exchangeIndex: number, citationIndex: number): string {
 66	  return `${exchangeIndex}:${citationIndex}`;
 67	}
 68	
 69	function UserTurn({ question }: { question: string }) {
 70	  return (
 71	    <div style={{
 72	      alignSelf: 'flex-end',
 73	      maxWidth: '85%',
 74	      minWidth: 0,
 75	      padding: '10px 14px',
 76	      background: palette.border,
 77	      borderRadius: '8px 8px 2px 8px',
 78	    }}>
 79	      <div style={turnLabel}>You</div>
 80	      <div style={textBlock}>{question}</div>
 81	    </div>
 82	  );
 83	}
 84	
 85	function CitationList({
 86	  citations,
 87	  exchangeIndex,
 88	  selectedDocId,
 89	  unavailable,
 90	  onActivate,
 91	}: {
 92	  citations: Citation[];
 93	  exchangeIndex: number;
 94	  selectedDocId: string | null;
 95	  unavailable: Set<string>;
 96	  onActivate: (citation: Citation, key: string) => void;
 97	}) {
 98	  if (citations.length === 0) {
 99	    return (
100	      <div style={{ marginTop: '10px', fontSize: '12px', color: palette.muted, fontStyle: 'italic' }}>
101	        No sources cited.
102	      </div>
103	    );
104	  }
105	
106	  return (
107	    <div style={{ marginTop: '12px' }}>
108	      <div style={{ ...turnLabel, marginBottom: '6px' }}>Sources ({citations.length})</div>
109	      <ul style={{ listStyle: 'none', display: 'flex', flexDirection: 'column', gap: '6px' }}>
110	        {citations.map((c, i) => {
111	          const key = citationKey(exchangeIndex, i);
112	          const isMissing = unavailable.has(key);
113	          const isSelected = selectedDocId === c.documentId;
114	          return (
115	            <li key={key}>
116	              <button
117	                type="button"
118	                onClick={() => onActivate(c, key)}
119	                title={`Open "${c.documentTitle}"`}
120	                style={{
121	                  display: 'block',
122	                  width: '100%',
123	                  textAlign: 'left',
124	                  padding: '8px 10px',
125	                  background: isSelected ? palette.border : palette.panel,
126	                  color: palette.text,
127	                  border: `1px solid ${palette.border}`,
128	                  borderLeft: `3px solid ${palette.accent}`,
129	                  borderRadius: '4px',
130	                  cursor: 'pointer',
131	                  fontSize: '12px',
132	                  lineHeight: 1.5,
133	                  overflowWrap: 'anywhere',
134	                }}
135	              >
136	                <span style={{ fontWeight: 600 }}>{c.documentTitle}</span>
137	                <span style={{ color: palette.muted }}> · chunk {c.chunkIndex}</span>
138	                {isSelected && <span style={{ color: palette.muted }}> · open</span>}
139	                <span style={{ display: 'block', marginTop: '2px', color: '#c0c0e0', whiteSpace: 'pre-wrap' }}>
140	                  “{c.excerpt}”
141	                </span>
142	                {isMissing && (
143	                  <span style={{ display: 'block', marginTop: '4px', color: palette.error }}>
144	                    This document is no longer available.
145	                  </span>
146	                )}
147	              </button>
148	            </li>
149	          );
150	        })}
151	      </ul>
152	    </div>
153	  );
154	}
155	
156	function Exchange({
157	  item,
158	  index,
159	  total,
160	  selectedDocId,
161	  unavailable,
162	  onActivate,
163	}: {
164	  item: QAHistory;
165	  index: number;
166	  total: number;
167	  selectedDocId: string | null;
168	  unavailable: Set<string>;
169	  onActivate: (citation: Citation, key: string) => void;
170	}) {
171	  const { response } = item;
172	  const confidence = describeConfidence(response.confidence);
173	  return (
174	    <article
175	      aria-label={`Exchange ${index + 1} of ${total}`}
176	      style={{ display: 'flex', flexDirection: 'column', gap: '8px' }}
177	    >
178	      <UserTurn question={item.question} />
179	      <div style={{
180	        alignSelf: 'stretch',
181	        minWidth: 0,
182	        padding: '12px 14px',
183	        background: palette.card,
184	        border: `1px solid ${palette.border}`,
185	        borderRadius: '8px 8px 8px 2px',
186	      }}>
187	        <div style={{ display: 'flex', flexWrap: 'wrap', gap: '4px 12px', alignItems: 'baseline', ...turnLabel }}>
188	          <span>Assistant</span>
189	          <time
190	            dateTime={response.timestamp}
191	            style={{ textTransform: 'none', letterSpacing: 0, fontWeight: 400 }}
192	          >
193	            {formatTimestamp(response.timestamp)}
194	          </time>
195	          <span style={{ textTransform: 'none', letterSpacing: 0, fontWeight: 400 }}>
196	            <span
197	              aria-hidden="true"
198	              style={{
199	                display: 'inline-block',
200	                width: '40px',
201	                height: '6px',
202	                marginRight: '6px',
203	                background: palette.border,
204	                borderRadius: '3px',
205	                overflow: 'hidden',
206	                verticalAlign: 'middle',
207	              }}
208	            >
209	              <span style={{
210	                display: 'block',
211	                width: `${confidence.percent}%`,
212	                height: '100%',
213	                background: palette.accent,
214	              }} />
215	            </span>
216	            Confidence: {confidence.level} ({confidence.percent}%)
217	          </span>
218	        </div>
219	        <div style={textBlock}>{response.answer}</div>
220	        <CitationList
221	          citations={response.citations}
222	          exchangeIndex={index}
223	          selectedDocId={selectedDocId}
224	          unavailable={unavailable}
225	          onActivate={onActivate}
226	        />
227	      </div>
228	    </article>
229	  );
230	}
231	
232	export function ConversationView({
233	  history,
234	  loadState,
235	  pendingQuestion,
236	  askError,
237	  documentCount,
238	  selectedDocId,
239	  onOpenCitation,
240	  onRetry,
241	  onDismissError,
242	  onReloadHistory,
243	  onClear,
244	}: Props) {
245	  const scrollRef = useRef<HTMLDivElement>(null);
246	  const clearButtonRef = useRef<HTMLButtonElement>(null);
247	  const cancelButtonRef = useRef<HTMLButtonElement>(null);
248	  const [confirmingClear, setConfirmingClear] = useState(false);
249	  const [clearFailed, setClearFailed] = useState(false);
250	  const [unavailable, setUnavailable] = useState<Set<string>>(() => new Set());
251	
252	  const busy = pendingQuestion !== null;
253	
254	  // Keep the newest exchange in view whenever a turn is added, resolved or fails.
255	  useEffect(() => {
256	    const el = scrollRef.current;
257	    if (el) el.scrollTop = el.scrollHeight;
258	  }, [history.length, pendingQuestion, askError, loadState]);
259	
260	  // Citation indices shift when history is cleared; drop stale "unavailable" marks.
261	  useEffect(() => {
262	    if (history.length === 0) setUnavailable(new Set());
263	  }, [history.length]);
264	
265	  useEffect(() => {
266	    if (confirmingClear) cancelButtonRef.current?.focus();
267	  }, [confirmingClear]);
268	
269	  const handleActivate = async (citation: Citation, key: string) => {
270	    const found = await onOpenCitation(citation);
271	    setUnavailable(prev => {
272	      if (found === !prev.has(key)) return prev;
273	      const next = new Set(prev);
274	      if (found) next.delete(key);
275	      else next.add(key);
276	      return next;
277	    });
278	  };
279	
280	  const cancelClear = () => {
281	    setConfirmingClear(false);
282	    // Return focus to the control that opened the confirmation.
283	    requestAnimationFrame(() => clearButtonRef.current?.focus());
284	  };
285	
286	  const confirmClear = async () => {
287	    const ok = await onClear();
288	    setClearFailed(!ok);
289	    setConfirmingClear(false);
290	  };
291	
292	  const showEmpty = loadState === 'loaded' && history.length === 0 && !busy && !askError;
293	
294	  return (
295	    <section
296	      aria-labelledby="conversation-heading"
297	      style={{ flex: 1, display: 'flex', flexDirection: 'column', minHeight: 0 }}
298	    >
299	      <div style={{
300	        display: 'flex',
301	        alignItems: 'center',
302	        justifyContent: 'space-between',
303	        flexWrap: 'wrap',
304	        gap: '8px',
305	        padding: '8px 20px',
306	        background: palette.panel,
307	        borderBottom: `1px solid ${palette.border}`,
308	      }}>
309	        <h2 id="conversation-heading" style={{ fontSize: '13px', fontWeight: 600 }}>
310	          Conversation
311	          <span style={{ color: palette.muted, fontWeight: 400 }}>
312	            {' '}({history.length} {history.length === 1 ? 'exchange' : 'exchanges'})
313	          </span>
314	        </h2>
315	        {confirmingClear ? (
316	          <div role="group" aria-label="Confirm clearing the conversation" style={{ display: 'flex', alignItems: 'center', gap: '8px', fontSize: '12px' }}>
317	            <span>Delete all {history.length} exchanges? This cannot be undone.</span>
318	            <button ref={cancelButtonRef} type="button" onClick={cancelClear} style={smallButton}>
319	              Cancel
320	            </button>
321	            <button
322	              type="button"
323	              onClick={confirmClear}
324	              style={{ ...smallButton, background: palette.accent, border: 'none', color: '#fff' }}
325	            >
326	              Clear conversation
327	            </button>
328	          </div>
329	        ) : (
330	          <button
331	            ref={clearButtonRef}
332	            type="button"
333	            onClick={() => setConfirmingClear(true)}
334	            disabled={history.length === 0 || busy}
335	            style={{
336	              ...smallButton,
337	              opacity: history.length === 0 || busy ? 0.5 : 1,
338	              cursor: history.length === 0 || busy ? 'default' : 'pointer',
339	            }}
340	          >
341	            Clear
342	          </button>
343	        )}
344	      </div>
345	
346	      {clearFailed && (
347	        <div role="alert" style={{ padding: '6px 20px', fontSize: '12px', color: palette.error }}>
348	          Could not clear the conversation. Please try again.
349	        </div>
350	      )}
351	
352	      <div
353	        ref={scrollRef}
354	        style={{ flex: 1, overflowY: 'auto', overflowX: 'hidden', padding: '16px 20px' }}
355	      >
356	        {loadState === 'loading' && (
357	          <div style={{ color: '#666', textAlign: 'center', paddingTop: '24px', fontSize: '13px' }}>
358	            Loading conversation…
359	          </div>
360	        )}
361	
362	        {loadState === 'error' && (
363	          <div role="alert" style={{ color: palette.error, textAlign: 'center', paddingTop: '24px', fontSize: '13px' }}>
364	            Could not load the conversation history.{' '}
365	            <button type="button" onClick={onReloadHistory} style={smallButton}>Try again</button>
366	          </div>
367	        )}
368	
369	        {showEmpty && (
370	          <div style={{ color: '#888', textAlign: 'center', paddingTop: '32px', fontSize: '13px', lineHeight: 1.6 }}>
371	            <div style={{ fontSize: '15px', color: palette.text, marginBottom: '6px' }}>No questions yet</div>
372	            Ask a question below. Each answer will appear here with the sources it cites,
373	            <br />
374	            and the conversation is kept between sessions.
375	            {documentCount === 0 && (
376	              <div style={{ marginTop: '8px', color: palette.muted }}>
377	                Tip: import and index documents first so answers can cite them.
378	              </div>
379	            )}
380	          </div>
381	        )}
382	
383	        <div role="log" aria-live="polite" aria-label="Conversation messages">
384	          <ol style={{ listStyle: 'none', display: 'flex', flexDirection: 'column', gap: '20px' }}>
385	            {history.map((item, i) => (
386	              <li key={`${item.response.timestamp}-${i}`}>
387	                <Exchange
388	                  item={item}
389	                  index={i}
390	                  total={history.length}
391	                  selectedDocId={selectedDocId}
392	                  unavailable={unavailable}
393	                  onActivate={handleActivate}
394	                />
395	              </li>
396	            ))}
397	
398	            {pendingQuestion !== null && (
399	              <li key="pending">
400	                <article aria-label="Question awaiting an answer" aria-busy="true" style={{ display: 'flex', flexDirection: 'column', gap: '8px' }}>
401	                  <UserTurn question={pendingQuestion} />
402	                  <div style={{
403	                    padding: '12px 14px',
404	                    background: palette.card,
405	                    border: `1px dashed ${palette.border}`,
406	                    borderRadius: '8px 8px 8px 2px',
407	                  }}>
408	                    <div style={turnLabel}>Assistant</div>
409	                    <div style={{ ...textBlock, color: palette.muted, fontStyle: 'italic' }}>Answering…</div>
410	                  </div>
411	                </article>
412	              </li>
413	            )}
414	
415	            {askError !== null && (
416	              <li key="error">
417	                <article aria-label="Question that could not be answered" style={{ display: 'flex', flexDirection: 'column', gap: '8px' }}>
418	                  <UserTurn question={askError.question} />
419	                  <div role="alert" style={{
420	                    padding: '12px 14px',
421	                    background: palette.card,
422	                    border: `1px solid ${palette.error}`,
423	                    borderRadius: '8px 8px 8px 2px',
424	                  }}>
425	                    <div style={{ ...turnLabel, color: palette.error }}>Not answered</div>
426	                    <div style={{ fontSize: '13px', lineHeight: 1.5 }}>
427	                      The question could not be answered.
428	                    </div>
429	                    <div style={{ fontSize: '12px', color: palette.muted, marginTop: '4px', overflowWrap: 'anywhere' }}>
430	                      Details: {askError.message}
431	                    </div>
432	                    <div style={{ display: 'flex', gap: '8px', marginTop: '10px' }}>
433	                      <button
434	                        type="button"
435	                        onClick={() => onRetry(askError.question)}
436	                        disabled={busy}
437	                        style={{ ...smallButton, background: palette.accent, border: 'none', color: '#fff' }}
438	                      >
439	                        Retry
440	                      </button>
441	                      <button type="button" onClick={onDismissError} style={smallButton}>
442	                        Dismiss
443	                      </button>
444	                    </div>
445	                  </div>
446	                </article>
447	              </li>
448	            )}
449	          </ol>
450	        </div>
451	      </div>
452	    </section>
453	  );
454	}

