231	
232	export function ConversationView({
233	  history,
234	  loadState,
235	  pendingQuestion,
236	  askError,
237	  documentCount,
238	  selectedDocId,
239	  onOpenCitation,
240	  onRetry,
241	  onDismissError,
242	  onReloadHistory,
243	  onClear,
244	}: Props) {
245	  const scrollRef = useRef<HTMLDivElement>(null);
246	  const clearButtonRef = useRef<HTMLButtonElement>(null);
247	  const cancelButtonRef = useRef<HTMLButtonElement>(null);
248	  const [confirmingClear, setConfirmingClear] = useState(false);
249	  const [clearFailed, setClearFailed] = useState(false);
250	  const [unavailable, setUnavailable] = useState<Set<string>>(() => new Set());
251	
252	  const busy = pendingQuestion !== null;
253	
254	  // Keep the newest exchange in view whenever a turn is added, resolved or fails.
255	  useEffect(() => {
256	    const el = scrollRef.current;
257	    if (el) el.scrollTop = el.scrollHeight;
258	  }, [history.length, pendingQuestion, askError, loadState]);
259	
260	  // Citation indices shift when history is cleared; drop stale "unavailable" marks.
261	  useEffect(() => {
262	    if (history.length === 0) setUnavailable(new Set());
263	  }, [history.length]);
264	
265	  useEffect(() => {
266	    if (confirmingClear) cancelButtonRef.current?.focus();
267	  }, [confirmingClear]);
268	
269	  const handleActivate = async (citation: Citation, key: string) => {
270	    const found = await onOpenCitation(citation);
271	    setUnavailable(prev => {
272	      if (found === !prev.has(key)) return prev;
273	      const next = new Set(prev);
274	      if (found) next.delete(key);
275	      else next.add(key);
276	      return next;
277	    });
278	  };
279	
280	  const cancelClear = () => {
281	    setConfirmingClear(false);
282	    // Return focus to the control that opened the confirmation.
283	    requestAnimationFrame(() => clearButtonRef.current?.focus());
284	  };
285	
286	  const confirmClear = async () => {
287	    const ok = await onClear();
288	    setClearFailed(!ok);
289	    setConfirmingClear(false);
290	  };
291	
292	  const showEmpty = loadState === 'loaded' && history.length === 0 && !busy && !askError;
293	
294	  return (
295	    <section
296	      aria-labelledby="conversation-heading"
297	      style={{ flex: 1, display: 'flex', flexDirection: 'column', minHeight: 0 }}
298	    >
299	      <div style={{
300	        display: 'flex',
301	        alignItems: 'center',
302	        justifyContent: 'space-between',
303	        flexWrap: 'wrap',
304	        gap: '8px',
305	        padding: '8px 20px',
306	        background: palette.panel,
307	        borderBottom: `1px solid ${palette.border}`,
308	      }}>
309	        <h2 id="conversation-heading" style={{ fontSize: '13px', fontWeight: 600 }}>
310	          Conversation
311	          <span style={{ color: palette.muted, fontWeight: 400 }}>
312	            {' '}({history.length} {history.length === 1 ? 'exchange' : 'exchanges'})
313	          </span>
314	        </h2>
315	        {confirmingClear ? (
316	          <div role="group" aria-label="Confirm clearing the conversation" style={{ display: 'flex', alignItems: 'center', gap: '8px', fontSize: '12px' }}>
317	            <span>Delete all {history.length} exchanges? This cannot be undone.</span>
318	            <button ref={cancelButtonRef} type="button" onClick={cancelClear} style={smallButton}>
319	              Cancel
320	            </button>
321	            <button
322	              type="button"
323	              onClick={confirmClear}
324	              style={{ ...smallButton, background: palette.accent, border: 'none', color: '#fff' }}
325	            >
326	              Clear conversation
327	            </button>
328	          </div>
329	        ) : (
330	          <button
331	            ref={clearButtonRef}
332	            type="button"
333	            onClick={() => setConfirmingClear(true)}
334	            disabled={history.length === 0 || busy}
335	            style={{
336	              ...smallButton,
337	              opacity: history.length === 0 || busy ? 0.5 : 1,
338	              cursor: history.length === 0 || busy ? 'default' : 'pointer',
339	            }}
340	          >
341	            Clear
342	          </button>
343	        )}
344	      </div>
345	
346	      {clearFailed && (
347	        <div role="alert" style={{ padding: '6px 20px', fontSize: '12px', color: palette.error }}>
348	          Could not clear the conversation. Please try again.
349	        </div>
350	      )}
351	
352	      <div
353	        ref={scrollRef}
354	        style={{ flex: 1, overflowY: 'auto', overflowX: 'hidden', padding: '16px 20px' }}
355	      >
356	        {loadState === 'loading' && (
357	          <div style={{ color: '#666', textAlign: 'center', paddingTop: '24px', fontSize: '13px' }}>
358	            Loading conversation…
359	          </div>
360	        )}
361	
362	        {loadState === 'error' && (
363	          <div role="alert" style={{ color: palette.error, textAlign: 'center', paddingTop: '24px', fontSize: '13px' }}>
364	            Could not load the conversation history.{' '}
365	            <button type="button" onClick={onReloadHistory} style={smallButton}>Try again</button>
366	          </div>
367	        )}
368	
369	        {showEmpty && (
370	          <div style={{ color: '#888', textAlign: 'center', paddingTop: '32px', fontSize: '13px', lineHeight: 1.6 }}>
371	            <div style={{ fontSize: '15px', color: palette.text, marginBottom: '6px' }}>No questions yet</div>
372	            Ask a question below. Each answer will appear here with the sources it cites,
373	            <br />
374	            and the conversation is kept between sessions.
375	            {documentCount === 0 && (
376	              <div style={{ marginTop: '8px', color: palette.muted }}>
377	                Tip: import and index documents first so answers can cite them.
378	              </div>
379	            )}
380	          </div>
381	        )}
382	
383	        <div role="log" aria-live="polite" aria-label="Conversation messages">
384	          <ol style={{ listStyle: 'none', display: 'flex', flexDirection: 'column', gap: '20px' }}>
385	            {history.map((item, i) => (
386	              <li key={`${item.response.timestamp}-${i}`}>
387	                <Exchange
388	                  item={item}
389	                  index={i}
390	                  total={history.length}
391	                  selectedDocId={selectedDocId}
392	                  unavailable={unavailable}
393	                  onActivate={handleActivate}
394	                />
395	              </li>
396	            ))}
397	
398	            {pendingQuestion !== null && (
399	              <li key="pending">
400	                <article aria-label="Question awaiting an answer" aria-busy="true" style={{ display: 'flex', flexDirection: 'column', gap: '8px' }}>
401	                  <UserTurn question={pendingQuestion} />
402	                  <div style={{
403	                    padding: '12px 14px',
404	                    background: palette.card,
405	                    border: `1px dashed ${palette.border}`,
406	                    borderRadius: '8px 8px 8px 2px',
407	                  }}>
408	                    <div style={turnLabel}>Assistant</div>
409	                    <div style={{ ...textBlock, color: palette.muted, fontStyle: 'italic' }}>Answering…</div>
410	                  </div>
411	                </article>
412	              </li>
413	            )}
414	
415	            {askError !== null && (
416	              <li key="error">
417	                <article aria-label="Question that could not be answered" style={{ display: 'flex', flexDirection: 'column', gap: '8px' }}>
418	                  <UserTurn question={askError.question} />
419	                  <div role="alert" style={{
420	                    padding: '12px 14px',
421	                    background: palette.card,
422	                    border: `1px solid ${palette.error}`,
423	                    borderRadius: '8px 8px 8px 2px',
424	                  }}>
425	                    <div style={{ ...turnLabel, color: palette.error }}>Not answered</div>
426	                    <div style={{ fontSize: '13px', lineHeight: 1.5 }}>
427	                      The question could not be answered.
428	                    </div>
429	                    <div style={{ fontSize: '12px', color: palette.muted, marginTop: '4px', overflowWrap: 'anywhere' }}>
430	                      Details: {askError.message}
431	                    </div>
432	                    <div style={{ display: 'flex', gap: '8px', marginTop: '10px' }}>
433	                      <button
434	                        type="button"
435	                        onClick={() => onRetry(askError.question)}
436	                        disabled={busy}
437	                        style={{ ...smallButton, background: palette.accent, border: 'none', color: '#fff' }}
438	                      >
439	                        Retry
440	                      </button>
441	                      <button type="button" onClick={onDismissError} style={smallButton}>
442	                        Dismiss
443	                      </button>
444	                    </div>
445	                  </div>
446	                </article>
447	              </li>
448	            )}
449	          </ol>
450	        </div>
451	      </div>
452	    </section>
453	  );
454	}

