  1	import { useState, useCallback, useEffect, useRef } from 'react';
  2	import { DocumentList } from './components/DocumentList';
  3	import { QuestionPanel } from './components/QuestionPanel';
  4	import { DocumentDetail } from './components/DocumentDetail';
  5	import { ConversationView, AskError, HistoryLoadState } from './components/ConversationView';
  6	import { StatusBar } from './components/StatusBar';
  7	import { describeAskError } from './components/conversation-format';
  8	import { Document, AppStatus, Citation, QAHistory } from '../shared/types';
  9	
 10	export function App() {
 11	  const [documents, setDocuments] = useState<Document[]>([]);
 12	  const [selectedDoc, setSelectedDoc] = useState<Document | null>(null);
 13	  const [appStatus, setAppStatus] = useState<AppStatus>({
 14	    documentsLoaded: 0,
 15	    indexStatus: 'idle',
 16	    lastActivity: '',
 17	  });
 18	  const [conversationHistory, setConversationHistory] = useState<QAHistory[]>([]);
 19	  const [historyLoadState, setHistoryLoadState] = useState<HistoryLoadState>('loading');
 20	  const [pendingQuestion, setPendingQuestion] = useState<string | null>(null);
 21	  const [askError, setAskError] = useState<AskError | null>(null);
 22	  // Synchronous guard: state updates are async, so two rapid submits could both see pendingQuestion === null.
 23	  const askInFlight = useRef(false);
 24	
 25	  const refreshDocuments = useCallback(async () => {
 26	    try {
 27	      const docs = await window.knowledgeBase.documents.list();
 28	      setDocuments(docs);
 29	      const status = await window.knowledgeBase.indexing.status();
 30	      setAppStatus(status);
 31	    } catch (err) {
 32	      console.error('Failed to refresh documents:', err);
 33	    }
 34	  }, []);
 35	
 36	  /** Loads the persisted conversation. Returns null if it could not be read. */
 37	  const loadHistory = useCallback(async (): Promise<QAHistory[] | null> => {
 38	    try {
 39	      const history = await window.knowledgeBase.conversation.get();
 40	      setConversationHistory(history);
 41	      setHistoryLoadState('loaded');
 42	      return history;
 43	    } catch {
 44	      // Keep whatever is already on screen; only report an error if nothing was ever loaded.
 45	      setHistoryLoadState(prev => (prev === 'loading' ? 'error' : prev));
 46	      return null;
 47	    }
 48	  }, []);
 49	
 50	  useEffect(() => {
 51	    refreshDocuments();
 52	    loadHistory();
 53	  }, [refreshDocuments, loadHistory]);
 54	
 55	  const handleImport = useCallback(async () => {
 56	    console.log('Import triggered - use window.knowledgeBase.documents.import(filePath)');
 57	  }, []);
 58	
 59	  const handleSelectDocument = useCallback((doc: Document) => {
 60	    setSelectedDoc(doc);
 61	  }, []);
 62	
 63	  const handleAskQuestion = useCallback(async (question: string) => {
 64	    if (askInFlight.current) return;
 65	    askInFlight.current = true;
 66	    setAskError(null);
 67	    setPendingQuestion(question);
 68	    try {
 69	      const response = await window.knowledgeBase.qa.ask(question);
 70	      // The service persists the exchange before replying, so the reloaded history already
 71	      // contains it. Replace the optimistic turn with the persisted one in the same synchronous
 72	      // block so no render shows the question twice.
 73	      let persisted: QAHistory[] | null = null;
 74	      try {
 75	        persisted = await window.knowledgeBase.conversation.get();
 76	      } catch {
 77	        persisted = null;
 78	      }
 79	      if (persisted) {
 80	        setConversationHistory(persisted);
 81	        setHistoryLoadState('loaded');
 82	      } else {
 83	        setConversationHistory(prev => [...prev, { question, response }]);
 84	      }
 85	      setPendingQuestion(null);
 86	    } catch (err) {
 87	      setAskError({ question, message: describeAskError(err) });
 88	      setPendingQuestion(null);
 89	    } finally {
 90	      askInFlight.current = false;
 91	    }
 92	  }, []);
 93	
 94	  const handleOpenCitation = useCallback(async (citation: Citation): Promise<boolean> => {
 95	    const known = documents.find(d => d.id === citation.documentId);
 96	    if (known) {
 97	      setSelectedDoc(known);
 98	      return true;
 99	    }
100	    // The list may be stale (e.g. documents seeded since the last refresh); ask main directly.
101	    try {
102	      const doc = await window.knowledgeBase.documents.get(citation.documentId);
103	      if (!doc) return false;
104	      setSelectedDoc(doc);
105	      refreshDocuments();
106	      return true;
107	    } catch {
108	      return false;
109	    }
110	  }, [documents, refreshDocuments]);
111	
112	  const handleClearConversation = useCallback(async (): Promise<boolean> => {
113	    try {
114	      await window.knowledgeBase.qa.clearHistory();
115	      setAskError(null);
116	      const reloaded = await loadHistory();
117	      if (reloaded === null) setConversationHistory([]);
118	      return true;
119	    } catch {
120	      return false;
121	    }
122	  }, [loadHistory]);
123	
124	  return (
125	    <div style={{ display: 'flex', flexDirection: 'column', height: '100vh' }}>
126	      <header style={{
127	        padding: '12px 20px',
128	        background: '#16213e',
129	        borderBottom: '1px solid #0f3460',
130	        display: 'flex',
131	        alignItems: 'center',
132	        justifyContent: 'space-between',
133	      }}>
134	        <h1 style={{ fontSize: '18px', fontWeight: 600 }}>Knowledge Base</h1>
135	        <button
136	          onClick={refreshDocuments}
137	          style={{
138	            padding: '6px 14px',
139	            background: '#0f3460',
140	            color: '#e0e0e0',
141	            border: '1px solid #1a1a4e',
142	            borderRadius: '4px',
143	            cursor: 'pointer',
144	            fontSize: '13px',
145	          }}
146	        >
147	          Refresh
148	        </button>
149	      </header>
150	
151	      <div style={{ display: 'flex', flex: 1, overflow: 'hidden' }}>
152	        {/* Left panel: document list */}
153	        <div style={{
154	          width: '280px',
155	          flexShrink: 0,
156	          borderRight: '1px solid #0f3460',
157	          display: 'flex',
158	          flexDirection: 'column',
159	          background: '#16213e',
160	        }}>
161	          <div style={{
162	            padding: '8px 16px',
163	            display: 'flex',
164	            alignItems: 'center',
165	            justifyContent: 'space-between',
166	            borderBottom: '1px solid #0f3460',
167	          }}>
168	            <h2 style={{ fontSize: '12px', fontWeight: 500 }}>
169	              Documents ({documents.length})
170	            </h2>
171	            <button
172	              onClick={handleImport}
173	              style={{
174	                padding: '4px 10px',
175	                background: '#533483',
176	                color: '#fff',
177	                border: 'none',
178	                borderRadius: '3px',
179	                cursor: 'pointer',
180	                fontSize: '12px',
181	              }}
182	            >
183	              + Import
184	            </button>
185	          </div>
186	          <DocumentList
187	            documents={documents}
188	            onSelect={handleSelectDocument}
189	            selectedId={selectedDoc?.id ?? null}
190	          />
191	        </div>
192	
193	        {/* Right panel: selected document (if any) above the conversation and question input */}
194	        <main style={{ flex: 1, minWidth: 0, display: 'flex', flexDirection: 'column', overflow: 'hidden' }}>
195	          {selectedDoc && (
196	            <section
197	              aria-label="Selected document"
198	              style={{
199	                flexShrink: 0,
200	                maxHeight: '40%',
201	                overflow: 'auto',
202	                padding: '16px 20px',
203	                borderBottom: '1px solid #0f3460',
204	                position: 'relative',
205	              }}
206	            >
207	              <button
208	                type="button"
209	                onClick={() => setSelectedDoc(null)}
210	                aria-label="Close document"
211	                style={{
212	                  float: 'right',
213	                  padding: '4px 10px',
214	                  background: 'transparent',
215	                  color: '#8888bb',
216	                  border: '1px solid #0f3460',
217	                  borderRadius: '4px',
218	                  cursor: 'pointer',
219	                  fontSize: '12px',
220	                }}
221	              >
222	                Close
223	              </button>
224	              <DocumentDetail key={selectedDoc.id} document={selectedDoc} />
225	            </section>
226	          )}
227	
228	          <ConversationView
229	            history={conversationHistory}
230	            loadState={historyLoadState}
231	            pendingQuestion={pendingQuestion}
232	            askError={askError}
233	            documentCount={documents.length}
234	            selectedDocId={selectedDoc?.id ?? null}
235	            onOpenCitation={handleOpenCitation}
236	            onRetry={handleAskQuestion}
237	            onDismissError={() => setAskError(null)}
238	            onReloadHistory={loadHistory}
239	            onClear={handleClearConversation}
240	          />
241	
242	          <QuestionPanel onAsk={handleAskQuestion} busy={pendingQuestion !== null} />
243	        </main>
244	      </div>
245	
246	      <StatusBar status={appStatus} />
247	    </div>
248	  );
249	}

